<section class="container section-top"><?php ff_heading('search','Find services, facilities, trainers, classes and stories.'); ?><form method="get" class="filter-bar"><input type="hidden" name="page" value="search"><input type="hidden" name="lang" value="<?=e($lang)?>"><label class="search-field"><span><?=e(t('search'))?></span><div><?=ff_icon('search')?><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="<?=e(t('What are you looking for?'))?>" maxlength="100"></div></label><label><span><?=e(t('category'))?></span><select name="kind"><option value=""><?=e(t('all_categories'))?></option><?php foreach(['service','facility','trainer','class_type','news'] as $v): ?><option value="<?=$v?>" <?=($_GET['kind']??'')===$v?'selected':''?>><?=e(t($v))?></option><?php endforeach ?></select></label><button class="button dark" type="submit"><?=e(t('search'))?> <?=ff_icon()?></button></form><div class="results-caption"><span><?=e((string)($total??count($items??[])))?> <?=e(t('results'))?></span></div><div class="card-grid three"><?php foreach($items??[] as $item)ff_card($item); ?></div><?php if(empty($items))ff_empty('No results found.','services');ff_pagination($pages??1,$pageNumber??1,'search'); ?></section>
